import{_ as e,o as r,c as n,a2 as o}from"./chunks/framework.BXyf8PVu.js";const p=JSON.parse('{"title":"Environmental, Social, and Governance (ESG) Considerations in Investment Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/CFA/C4 Corporate Finance/M2 ESG.md","filePath":"blogs/CFA/C4 Corporate Finance/M2 ESG.md"}'),a={name:"blogs/CFA/C4 Corporate Finance/M2 ESG.md"};function s(i,t,d,l,c,g){return r(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="environmental-social-and-governance-esg-considerations-in-investment-analysis" tabindex="-1">Environmental, Social, and Governance (ESG) Considerations in Investment Analysis <a class="header-anchor" href="#environmental-social-and-governance-esg-considerations-in-investment-analysis" aria-label="Permalink to &quot;Environmental, Social, and Governance (ESG) Considerations in Investment Analysis&quot;">​</a></h1><p>How ownership structures shape corporate governance, how to evaluate a company&#39;s governance, and how to identify ESG risks and opportunities and build them into equity and credit analysis. The module is conceptual: there are no formulas to memorize.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Controlling shareholders</strong></td><td>An individual or group (a family, other companies, the state) able to exercise control, holding either a <strong>majority</strong> (&gt; 50%) <strong>or a minority</strong> (&lt; 50%) of the shares</td></tr><tr><td><strong>Principal–agent problem</strong></td><td>Managers use company resources for their own interests instead of shareholders&#39;</td></tr><tr><td><strong>Principal–principal problem</strong></td><td>Controlling shareholders take resources at the expense of minority shareholders</td></tr><tr><td><strong>Voting caps</strong></td><td>Legal limits on the votes of large holdings (often used by governments to deter foreign control of strategic companies)</td></tr><tr><td><strong>Interlocking directorates</strong></td><td>The same people sit on the boards of several companies (common in Latin America)</td></tr><tr><td><strong>Insiders</strong></td><td>Managers and directors who are also shareholders</td></tr><tr><td><strong>Shareholder activism</strong></td><td>Strategies shareholders use to push a company to act in a certain way</td></tr><tr><td><strong>ESG integration</strong></td><td>Using ESG factors, qualitative and quantitative, in security and industry analysis <strong>and portfolio construction</strong></td></tr><tr><td><strong>Stranded assets</strong></td><td>Assets made obsolete or uneconomic, often by regulation or shifts in demand</td></tr><tr><td><strong>Greenwashing</strong></td><td>The risk that a green bond&#39;s proceeds don&#39;t actually fund a beneficial environmental project</td></tr></tbody></table><h2 id="ownership-structure" tabindex="-1">Ownership Structure <a class="header-anchor" href="#ownership-structure" aria-label="Permalink to &quot;Ownership Structure&quot;">​</a></h2><ul><li><strong>Dispersed ownership</strong>: many shareholders, none able to exercise control alone.</li><li><strong>Concentrated ownership</strong>: one shareholder or a group (controlling shareholders) can exercise control.</li><li><strong>Hybrid</strong>: in between.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>There are no fixed percentage cut-offs. Ownership alone may not show who controls a company: controlling shareholders can hold a <strong>majority or a minority</strong> of the shares, through the arrangements below. (The only &quot;25%&quot; in the reading describes the UK, where few companies have a holder with 25% or more.)</p></div><p>Concentrated ownership is far more common: <strong>38 of 47</strong> jurisdictions surveyed by the OECD (2017).</p><table tabindex="0"><thead><tr><th>Classification</th><th>Jurisdictions</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Dispersed</strong></td><td>Australia, Ireland, UK, US</td><td>Australia: shares held mostly by financial institutions; US listed companies rarely have a controlling holder</td></tr><tr><td><strong>Hybrid</strong></td><td>Canada, Germany, Japan, Netherlands, Switzerland</td><td>e.g., Germany: many companies under tight control, but listed shares widely held</td></tr><tr><td><strong>Concentrated</strong></td><td>The other 38 (e.g., China, France, India, Brazil, South Korea)</td><td>State: China, Norway, Sweden. Families: Brazil, Mexico, Portugal, South Korea. Company groups: India, Russia</td></tr></tbody></table><p><strong>How control can exceed ownership:</strong></p><ul><li><strong>Horizontal ownership</strong>: companies with shared business interests (key customers or suppliers) hold shares in each other. It supports strategic alliances and long-term relationships.</li><li><strong>Vertical (pyramid) ownership</strong>: a company or group controls two or more holding companies, which in turn control operating companies.</li><li><strong>Dual-class shares</strong>: one class has superior (or sole) voting rights, others have inferior or none. Combined with a pyramid, the group at the top can give itself the superior-voting shares and control the operating companies while owning relatively few shares.</li></ul><h3 id="conflicts-by-ownership-structure" tabindex="-1">Conflicts by Ownership Structure <a class="header-anchor" href="#conflicts-by-ownership-structure" aria-label="Permalink to &quot;Conflicts by Ownership Structure&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ownership</th><th>Voting power</th><th>Balance of power</th><th>Main conflict</th></tr></thead><tbody><tr><td>Dispersed</td><td>Dispersed</td><td>Weak shareholders, <strong>strong managers</strong></td><td><strong>Principal–agent</strong></td></tr><tr><td>Concentrated</td><td>Concentrated</td><td><strong>Strong shareholders</strong>, weak managers</td><td><strong>Principal–principal</strong></td></tr><tr><td>Dispersed</td><td>Concentrated</td><td>Controlling holders <strong>without a majority</strong> (via dual-class shares, pyramids)</td><td><strong>Principal–principal</strong></td></tr><tr><td>Concentrated</td><td>Dispersed</td><td>Arises from <strong>voting caps</strong></td><td>(not named in the reading)</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Controlling shareholders <strong>reduce</strong> the principal–agent problem (they control the board, appoint managers, and have the incentive to monitor), but they <strong>create</strong> the principal–principal problem.</p></div><h3 id="influential-shareholders" tabindex="-1">Influential Shareholders <a class="header-anchor" href="#influential-shareholders" aria-label="Permalink to &quot;Influential Shareholders&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shareholder</th><th>Role and concerns</th></tr></thead><tbody><tr><td><strong>Banks</strong></td><td>Common in Europe and Asia; both lender <strong>and</strong> shareholder. May push the company into large loans on unfavorable terms, at other shareholders&#39; expense</td></tr><tr><td><strong>Families</strong></td><td>Predominant in Latin America, less so in Asia and Europe; often with interlocking directorates. <strong>+</strong> fewer principal–agent problems. <strong>−</strong> poor transparency, weak management accountability, little regard for minority rights, hard to attract top managers</td></tr><tr><td><strong>State-owned enterprises</strong></td><td>In strategic sectors, or where capital needs exceed the private sector, or where the state wants products at a set price or standard (power, health). A listed SOE (<strong>mixed ownership</strong>) faces less market scrutiny (implicit state guarantee against bankruptcy) and may pursue public policy at shareholders&#39; expense</td></tr><tr><td><strong>Institutional investors</strong></td><td>Mutual funds, pension funds, insurers, hedge funds; have the resources and expertise to judge. In dispersed markets rarely large enough to control, but promote good governance by holding boards and managers accountable</td></tr><tr><td><strong>Group companies</strong></td><td>Horizontal or vertical structures give control out of proportion to ownership; cross-holdings restrict share transfers and keep outsiders out. Higher risk of <strong>related-party transactions</strong> against minority holders (e.g., Samsung, Sanwa, Grupo Carso)</td></tr><tr><td><strong>Private equity</strong></td><td>Venture capital (early stage, oversight) and LBO firms (majority control of mature companies); may bring corporate codes and performance-based pay</td></tr><tr><td><strong>Foreign investors</strong></td><td>Influential in emerging markets when they own more than domestic investors; those from stricter jurisdictions may demand more transparency. Cross-listing in a stricter market can benefit local minority holders</td></tr><tr><td><strong>Insiders</strong></td><td>Larger stakes → better alignment with shareholders and a long-term focus; but large stakes can also give them the power to protect their own interests</td></tr></tbody></table><h3 id="effects-on-governance" tabindex="-1">Effects on Governance <a class="header-anchor" href="#effects-on-governance" aria-label="Permalink to &quot;Effects on Governance&quot;">​</a></h3><ul><li><strong>Independent directors</strong>: directors with no material relationship with the company (employment, ownership or pay). They originated in dispersed-ownership jurisdictions to strengthen monitoring of managers, and their share rose after scandals such as Enron. The US requires audit, nomination and compensation committees made up entirely of independent directors. In most concentrated jurisdictions, nomination and remuneration committees aren&#39;t mandatory, and independent directors play a narrower role. OECD countries require or recommend either a minimum number (typically 1–3) or a minimum share (typically 20% to more than 50%).</li><li><strong>Board structure</strong>: <ul><li><strong>One-tier</strong>: a single board of executive and non-executive directors. The most common structure.</li><li><strong>Two-tier</strong>: a supervisory board oversees a management board. Mandatory in, e.g., Argentina, Germany and Russia; optional in Brazil and France. The supervisory board inspects the books, reviews the annual report, oversees the auditors and sets or influences management pay; in Germany, it includes stakeholder representatives (banks, labor).</li></ul></li><li><strong>Special voting arrangements</strong>: help minority holders take part in nominating and electing directors (e.g., Brazil, India, Portugal, Turkey, Italy, Israel, UK). In the UK, a premium-listed company with a controlling holder must have its independent directors approved by <strong>both</strong> all shareholders <strong>and</strong> the non-controlling shareholders.</li><li><strong>Governance codes, laws and listing rules</strong>: national codes work on a <strong>comply-or-explain</strong> basis. Japan goes further: a company with no outside directors must explain why appointing them isn&#39;t appropriate. Without a national code, company law (e.g., Chile) or exchange listing rules (e.g., India) apply.</li><li><strong>Stewardship codes</strong>: mostly voluntary codes encouraging investors to use their rights and engage. Under the UK Stewardship Code, institutional investors must monitor the companies they invest in, and UK asset managers must publish a comply-or-explain statement.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The principal–agent problem is generally <strong>smaller</strong> under concentrated ownership, which is why independent directors play a narrower role there.</p></div><h2 id="evaluating-corporate-governance" tabindex="-1">Evaluating Corporate Governance <a class="header-anchor" href="#evaluating-corporate-governance" aria-label="Permalink to &quot;Evaluating Corporate Governance&quot;">​</a></h2><p>Effective governance can bring higher profitability and ROE growth, better access to credit, higher and sustainable dividends, good long-term share performance and a <strong>lower cost of capital</strong>. Ineffective governance brings reputational damage, weaker competitiveness, a weak or volatile share price, lower profitability and a <strong>higher cost of capital</strong>.</p><p>Governance is hard to quantify. Start with the disclosed policies (including business ethics, bribery and corruption, whistleblower protection and related-party transactions), then engage with management, and use activism if needed. In practice, analysts reflect governance by adjusting the <strong>risk premium (cost of capital) or the credit spread</strong>.</p><h3 id="board-policies-and-practices" tabindex="-1">Board Policies and Practices <a class="header-anchor" href="#board-policies-and-practices" aria-label="Permalink to &quot;Board Policies and Practices&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>What to look for</th></tr></thead><tbody><tr><td><strong>CEO duality</strong></td><td>CEO also chairs the board → the board&#39;s oversight may suffer. If the chair isn&#39;t independent, a <strong>lead independent director</strong> may be appointed</td></tr><tr><td><strong>Board independence</strong></td><td>No independent directors, or only a minority, is a <strong>negative</strong>: management may act in its own interest → higher perceived risk</td></tr><tr><td><strong>Committees</strong></td><td>Audit, governance, remuneration, nomination, risk, compliance. Check that key committees are independent: non-independent or executive members create conflicts over pay (remuneration), management selection (nomination) and reporting integrity (audit)</td></tr><tr><td><strong>Skills and experience</strong></td><td>Skills that are too concentrated, or diverse but unrelated to the core business, may both fall short. In resource or high-ESG-risk sectors, boards typically include environmental, climate or social expertise</td></tr><tr><td><strong>Tenure</strong></td><td>Over <strong>10 years</strong> is long. <strong>+</strong> deep knowledge of the business and of management&#39;s record; <strong>−</strong> may weaken independence (too close to management) and resist change</td></tr><tr><td><strong>Composition</strong></td><td>Number and diversity of directors (professional, cultural and geographic background, gender, age, tenure). Too many members or too little diversity can govern less effectively</td></tr><tr><td><strong>Board evaluation</strong></td><td>Self-evaluation or external review, covering duties, leadership, structure (including committees) and board–management relations; may be aimed at shareholders, regulators or other stakeholders</td></tr></tbody></table><p><strong>Executive remuneration.</strong> Look for transparency; short- and long-term incentive criteria; a link to the company&#39;s strategy; and the pay gap between the CEO and the average worker. Excessive pay (often CEO pay ÷ average-worker pay) is judged against KPIs: do the incentives drive company value?</p><ul><li><strong>Say on pay</strong>: <strong>shareholders</strong> can vote on, or give feedback on, remuneration.</li><li><strong>Clawback</strong>: the company can <strong>recover pay already awarded</strong> if restatements, misconduct, breaches of law or risk-management failures come to light.</li></ul><p><strong>Voting rights.</strong> <strong>Straight voting</strong> (one share, one vote) vs <strong>dual-class</strong> shares, where founders or managers hold higher-vote shares than the public: a potential conflict with minority holders.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Separating the CEO and chair roles is positive, but not the whole story: low independence, long tenure and family or insider dominance can still make a board weak.</p></div><h2 id="identifying-esg-factors" tabindex="-1">Identifying ESG Factors <a class="header-anchor" href="#identifying-esg-factors" aria-label="Permalink to &quot;Identifying ESG Factors&quot;">​</a></h2><p>The main challenge is getting information that is <strong>relevant, comparable and decision-useful</strong>. ESG data come mostly from public filings and sustainability reports (which may or may not be independently assured); most ESG disclosure is <strong>voluntary</strong> and <strong>inconsistent</strong>, though it has increased over time.</p><p><strong>Materiality.</strong> An ESG issue is material if it is expected to affect a company&#39;s operations, financial performance and the valuation of its securities, whether positively or negatively. Companies may call positive but immaterial information &quot;material&quot; while downplaying negative information that investors would consider material.</p><p><strong>Investment horizon.</strong> Whether an issue matters also depends on the horizon:</p><ul><li>Horizon matters especially for <strong>credit analysts</strong>, because bonds have different maturities.</li><li>An issue&#39;s horizon can shift from long term to short term (or back) after a regulation change or a controversy such as an oil spill.</li><li>E.g., a manufacturer faces stricter future environmental rules: a short-horizon investor sees little effect on near-term profit; a long-horizon investor expects costly plant upgrades or fines.</li></ul><p><strong>Relevant factors by industry.</strong> Governance best practice is fairly consistent across companies (though it varies by region). For environmental and social factors there is <strong>no global best practice</strong>: relevance depends on the industry. Energy companies are more exposed to <strong>environmental</strong> factors; banks to <strong>social</strong> ones (data security, privacy, customer satisfaction); both to governance.</p><p><strong>Three ways to identify ESG factors</strong> (alone or combined):</p><table tabindex="0"><thead><tr><th>Approach</th><th>What it is</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Proprietary methods</strong></td><td>The analyst&#39;s or firm&#39;s own judgment and tools, drawing on companies, news, industry and environmental groups, labor organizations, experts and government</td><td>Annual, sustainability and proxy reports, 10-K; TCFD-aligned climate scenario disclosures (transition and physical risks)</td></tr><tr><td><strong>ESG data providers</strong></td><td>Vendors turn public disclosures into ESG scores and rankings (often industry-relative), with some subjective analyst assessment</td><td>MSCI, Sustainalytics</td></tr><tr><td><strong>Not-for-profit initiatives and reporting frameworks</strong></td><td>Data, insights and tools on ESG issues</td><td>IIRC (standardized disclosure framework), GRI (sustainability reporting standards by industry), SASB (uniform sustainability accounting standards; <strong>materiality maps</strong>), 2DII, Access to Nutrition Index</td></tr></tbody></table><p>Disclosures range from minimal to many pages, which makes comparisons hard. For example, GRI&#39;s topics for consumer durables and household and personal products include environmental ones (materials sourcing, packaging, plastic and chemicals, product energy efficiency), social ones (migrant workers, product safety, labeling, e-waste) and others (executive pay, gender on governance bodies, supplier screening).</p><h2 id="esg-integration" tabindex="-1">ESG Integration <a class="header-anchor" href="#esg-integration" aria-label="Permalink to &quot;ESG Integration&quot;">​</a></h2><p>ESG integration aims to identify opportunities and reduce downside risk.</p><table tabindex="0"><thead><tr><th></th><th>Equity</th><th>Fixed income (credit)</th></tr></thead><tbody><tr><td>Purpose</td><td>Identify <strong>opportunities and</strong> reduce downside risk</td><td>Mainly <strong>reduce downside risk</strong> (the best case is repayment at par)</td></tr><tr><td>Techniques</td><td>Forecast financials and ratios, adjust valuation inputs (e.g., the <strong>discount rate</strong>), sensitivity and scenario analysis</td><td>Internal credit assessments, forecast ratios, relative credit ranking; relative value, <strong>spread</strong>, <strong>duration</strong>, sensitivity and scenario analysis</td></tr><tr><td>Illustrations</td><td>Hotel: raise operating costs for high staff turnover. Snack maker: <strong>lower</strong> the discount rate for switching to a sustainable key ingredient</td><td>Toy maker: lawsuits hurt credit ratios, cash flow and liquidity; spreads may widen. Coal company: stranded-asset risk hurts its <strong>10-year</strong> notes much more than its <strong>1-year</strong> notes</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Identification and integration are similar for equity and credit, but the <strong>material factors and their implications differ</strong>, and the credit (and CDS) effect can differ by <strong>maturity</strong>.</p></div><h3 id="green-bonds" tabindex="-1">Green Bonds <a class="header-anchor" href="#green-bonds" aria-label="Permalink to &quot;Green Bonds&quot;">​</a></h3><p>A <strong>green bond</strong> funds projects with environmental or climate benefits: its proceeds are designated for specific green projects.</p><ul><li>The first was the European Investment Bank&#39;s Climate Awareness Bond, in <strong>2007</strong>.</li><li>The issuer decides on the &quot;green&quot; label with its lead underwriter, must disclose the eligibility criteria and use of proceeds, and may commission independent reviews. The <strong>Green Bond Principles</strong> (2014; voluntary; maintained by ICMA) guide this; index providers, rating agencies and the Climate Bonds Initiative have their own methods, and the European Commission is developing criteria.</li><li>For the issuer: extra monitoring and reporting costs, but a wider investor base and potentially a lower yield at issue.</li><li>Forms: plain corporates, project bonds, MBS/ABS and municipals (e.g., California&#39;s US$300 million green general obligation bond of 2014, backed by the General Fund like its other GO bonds).</li><li><strong>Same rating and valuation</strong> as the issuer&#39;s conventional bonds (all else equal): only the use of proceeds differs, and bondholders have the same recourse.</li><li>May trade at a premium (tighter spread) <strong>because of demand</strong>, not because it is less risky.</li><li>Risks: <strong>greenwashing</strong> (overpaying for a green feature, or holding a bond that fails an environmental mandate) and <strong>liquidity</strong> (many holders buy and hold).</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>A green bond&#39;s credit risk is the issuer&#39;s credit risk. A tighter spread reflects <strong>demand</strong>, not lower default risk.</p></div><h2 id="evaluating-esg-risks-and-opportunities" tabindex="-1">Evaluating ESG Risks and Opportunities <a class="header-anchor" href="#evaluating-esg-risks-and-opportunities" aria-label="Permalink to &quot;Evaluating ESG Risks and Opportunities&quot;">​</a></h2><p>The integration process:</p><ol><li>Identify the <strong>material</strong> ESG factors for the company and its industry.</li><li>Evaluate them over time, in forecasts, and against peers.</li><li>Adjust the financial statements and the valuation:</li></ol><table tabindex="0"><thead><tr><th>Where</th><th>Typical ESG adjustments</th></tr></thead><tbody><tr><td>Income statement / cash flow</td><td>Revenue, operating and non-operating costs, margins, earnings, capex</td></tr><tr><td>Balance sheet</td><td>Estimates of <strong>impaired assets</strong></td></tr><tr><td>Equity valuation</td><td>Cost of capital / <strong>discount rate</strong>, price multiple, terminal value</td></tr><tr><td>Bond valuation</td><td><strong>Credit spread</strong> or CDS</td></tr></tbody></table><p>The <em>Guidance and Case Studies for ESG Integration: Equities and Fixed Income</em> (2018) framework covers research (qualitative and quantitative), security valuation, portfolio construction, asset allocation, scenario analysis and risk management.</p><p>The reading&#39;s three cases each focus on one pillar; the ideas carry over to other industries:</p><table tabindex="0"><thead><tr><th>Case</th><th>Pillar</th><th>Key metric</th><th>Financial adjustment</th><th>Valuation effect</th></tr></thead><tbody><tr><td><strong>Frizzle Drinks</strong> (US beverages)</td><td>Environmental</td><td><strong>Water intensity</strong> = liters of water per liter of product (normalized per US$1 million of revenue for peer comparison)</td><td>Fell 27% from 2009 to 2021, target another 13% by 2025. COGS/revenue 2022F 40% (peers 42%), cut by 1% for lower water use → higher gross margin</td><td>Higher earnings → higher fair value of the stock; better operating cash flow for bonds and CDS; check whether lower ESG risk is <strong>already in spreads</strong></td></tr><tr><td><strong>Well Pharma</strong> (European pharma)</td><td>Social</td><td><strong>Product quality</strong>: controversies, regulatory warning letters, recalls, fines, % of plants certified (e.g., ISO 9001)</td><td>Worst record among peers (15 warning letters, 5 quality controversies). Revenue −2% next year; COGS/revenue +1.3%; non-operating expenses +4.5% of operating income. Treatment depends on whether issues are <strong>recurring or one-off</strong></td><td>Lower earnings and cash flow for shareholders <strong>and</strong> bondholders; possible impairment of brand value</td></tr><tr><td><strong>Sumiyoshi</strong> (Japanese bank)</td><td>Governance</td><td>Board composition vs peers; <strong>NPLs / total loans</strong> as a governance proxy</td><td>NPL ratio 50 bp above peers</td><td>Higher equity risk premium; wider credit spread</td></tr></tbody></table><p>How Well Pharma&#39;s quality issues flow into the financials:</p><table tabindex="0"><thead><tr><th>Factor</th><th>Financial impact</th></tr></thead><tbody><tr><td>Product quality controversies</td><td>Brand damage → lower sales</td></tr><tr><td>Regulatory warning letters</td><td>Higher compliance costs</td></tr><tr><td>Product recalls</td><td>Lost revenue; recall costs</td></tr><tr><td>Regulatory fines</td><td>Provisions for sales returns and litigation</td></tr><tr><td>Low share of certified plants</td><td>Higher risk of quality problems, recalls and costs</td></tr></tbody></table>',53)])])}const u=e(a,[["render",s]]);export{p as __pageData,u as default};
